\begin{center}
\textbf{মানব শারীরতত্ত্ব : শ্বসন ও শ্বাসক্রিয়া} \\
\textbf{Human Physiology : Respiration \& Breathing}
\end{center}

\begin{table}[h]
\centering
\begin{tabular}{|c|c|}
\hline
\textbf{প্রধান শব্দাবলি (Key words)} & \\
\hline
অ্যালভিওলাই & প্লিউরা \\
\hline
শ্বাসরঞ্জক & ওটাইটিস মিডিয়া \\
\hline
সাইনুসাইটিস & কৃত্রিম শ্বাস-প্রশস্ত \\
\hline
\end{tabular}
\end{table}

\begin{center}
\textbf{এ অধ্যায়ের পাঠগুলো পড়ে যা যা শিক্ষা} \\
\begin{tabular}{|p{10cm}|p{5cm}|}
\hline
\textbf{পাঠ ১} & মানুষের শ্বাসনতন্ত্রের বিভিন্ন অংশের গঠনের সাথে কাজের সম্পর্ক নির্ণয় \\
\hline
\textbf{পাঠ ২} & ব্যবহারিক: মানুষের ফুসফুসের অনুচ্ছেদ শনাক্তকরণ ও চিত্র অঙ্কন \\
\hline
\textbf{পাঠ ৩} & প্রশাস-নিয়ন্ত্রণ কার্যক্রম ও নিয়ন্ত্রণ প্রক্রিয়া \\
\hline
\textbf{পাঠ ৪} & গ্যাসীয় পরিবহন: O₂ পরিবহন \\
\hline
\textbf{পাঠ ৫} & গ্যাসীয় পরিবহন: CO₂ পরিবহন \\
\hline
\textbf{পাঠ ৬} & শ্বাসরঞ্জক \\
\hline
\textbf{পাঠ ৭ ও ৮} & শ্বাসনালির সমস্যা, লক্ষণ ও প্রতিকার: সাইনুসাইটিস, ওটাইটিস মিডিয়া \\
\hline
\textbf{পাঠ ৯} & ফুসফুসের এক্স-রে চিত্রের তুলনা \\
\hline
\textbf{পাঠ ১০} & কৃত্রিম শ্বাস-প্রশস্ত \\
\hline
\end{tabular}
\end{center}

\begin{center}
\textbf{মানুষের শ্বাসনতন্ত্র (Human Respiratory System)} \\
\end{center}

\begin{center}
\textbf{মানুষের শ্বাস অঙ্গ হচ্ছে একজোড়া ফুসফুস (lungs)}। যে পথ দিয়ে ফুসফুসে বায়ু প্রবেশ করে এবং ফুসফুস থেকে তা বহিঃগত হয় তাকে শ্বাসন পথ (respiratory passage) বলে। সম্মুখ নাসারূক্ষ থেকে শ্বাসন পথের শুরু। মানুষের শ্বাসনতন্ত্রের পর্যায়ক্রমিক বিভিন্ন অংশকে নিচে বর্ণিত উত্তর অংশে ভাগ করে বর্ণনা করা যায়।
\end{center}

\begin{center}
\textbf{মানুষের অংশগুলি} \\
\begin{tabular}{|p{5cm}|p{5cm}|p{5cm}|}
\hline
\textbf{ক. বায়ু গ্রহণ ও ত্যাগ অংশগুলি} & \textbf{খ. বায়ু পরিবহন অংশগুলি} & \textbf{গ. শ্বাসন অংশগুলি} \\
\hline
সম্মুখ নাসারূক্ষ, ভেস্টিবিউল, নাসাগুবর্ব, পশ্চাত নাসারূক্ষ, নাসাগলবিল, স্বরযন্ত্র। & ট্রাকিয়া, ব্রষ্কি, প্রাঙ্গিয়া ব্রন্ডিওল। & শ্বাসন ব্রন্ডিওল, অ্যালভিওলার নালি, অ্যাট্রিয়াম, অ্যালভিওলার থলি, অ্যালভিওলাস। \\
\hline
\end{tabular}
\end{center}

